window.RA_DATA = window.RA_DATA || {};
window.RA_DATA.lines = [
  { id: "heike-s1", kind: "scene", book_id: "tale-of-the-heike", place_ids: ["jp-akama-jingu"], location: "Book 11, 'The Drowning of the Former Emperor'", location_zh: "卷十一《先帝投海》", text_en: "As the Heike fleet is crushed at Dan-no-ura, the emperor's grandmother, the Nun of the Second Rank, takes the eight-year-old Antoku in her arms with the sacred sword and jewel. When he asks where they are going, she tells him to bow to the east and say farewell to the Ise shrine, then to the west and pray to the Buddha, and says there is a capital beneath the waves, before leaping into the sea.", text_zh: "平家船队在坛之浦被击溃，天皇的外祖母二位尼抱起八岁的安德天皇，带着神剑和神玺。天皇问要去哪里，她让他先向东拜别伊势神宫，再向西念佛，然后说“波浪底下也有都城”，抱着他跳进了海里。", highlight_en: ["capital beneath the waves"], highlight_zh: ["波浪底下也有都城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Tale_of_the_Heike" },
  { id: "sonezaki-s1", kind: "scene", book_id: "sonezaki-shinju", place_ids: ["jp-tsuyu-tenjin"], location: "Act 3, 'The Journey'", location_zh: "第三场《道行》", text_en: "Tokubei, a soy-sauce shop clerk, has been cheated of his money by a friend and publicly shamed, and cannot marry the courtesan Ohatsu. Slipping out of the brothel before dawn, the two walk through the sleeping town to the forest of Tsuyu no Tenjin, tie themselves to a tree and die together, sure they will be reborn on the same lotus.", text_zh: "酱油铺伙计德兵卫被朋友骗走了钱，当众受辱，没法娶游女阿初。天亮前，两人偷偷溜出妓楼，穿过沉睡的街市来到露天神社的树林，把自己绑在一棵树上，一起死去，相信来世能同生在一朵莲花上。", highlight_en: ["same lotus"], highlight_zh: ["一朵莲花上"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Love_Suicides_at_Sonezaki" },
  { id: "chushin-s1", kind: "scene", book_id: "chushingura", place_ids: ["jp-sengakuji"], location: "Acts 4 and 11", location_zh: "第四段与第十一段", text_en: "Insulted by the corrupt Ko no Moronao, Lord Enya draws his sword in the shogun's palace and is ordered to commit seppuku; his chief retainer Oboshi Yuranosuke arrives just as he dies. Pretending for a year to be a drunkard in the pleasure quarters, Yuranosuke gathers forty-seven loyal ronin, and on a snowy night they storm Moronao's mansion and take his head.", text_zh: "盐冶判官受到贪婪的高师直侮辱，在将军府拔刀，被勒令切腹；首席家老大星由良之助赶到时他刚刚断气。由良之助在花街装了一年醉鬼，暗中聚集四十七名忠心的浪士，一个雪夜，他们攻进师直的宅邸，取下了他的首级。", highlight_en: ["forty-seven loyal ronin"], highlight_zh: ["四十七名忠心的浪士"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Kanadehon_Ch%C5%ABshingura" },
  { id: "tono-s1", kind: "scene", book_id: "tono-monogatari", place_ids: ["jp-kappabuchi"], location: "Tales 55–59", location_zh: "第五十五至五十九则", text_en: "In the rivers of Tono there are many kappa. In one village a woman bore a kappa's child two generations running; the babies' bodies were cut up and buried in casks. Another kappa tried to drag a horse into the pool, but the horse dragged the kappa all the way to the stable, where it hid under the manger and was caught, and had to promise never to do mischief again.", text_zh: "远野的河里有很多河童。有个村子里，一家的女人连着两代生下河童的孩子，婴儿被砍碎装进木桶埋了。还有一只河童想把马拖进深潭，反被马一路拖回马厩，躲在马槽下面被人抓住，只好发誓再也不干坏事。", highlight_en: ["many kappa"], highlight_zh: ["很多河童"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/T%C5%8Dno_Monogatari" },
  { id: "musashi-s1", kind: "scene", book_id: "musashi", place_ids: ["jp-ganryujima"], location: "Final chapter", location_zh: "最后一章", text_en: "Miyamoto Musashi, the wild young man from Mimasaka who has spent years learning to master himself as well as the sword, is to fight the brilliant Sasaki Kojiro on the island of Funashima. He arrives hours late, on a hired boat, with a wooden sword he has carved from an oar on the way; Kojiro throws away his scabbard in fury, and Musashi kills him with a single blow.", text_zh: "宫本武藏原是美作乡下的野小子，多年来既学剑也学着驾驭自己，如今要在舟岛与才华横溢的佐佐木小次郎决斗。他坐着雇来的小船迟到了几个小时，手里是路上用船桨削成的木刀；小次郎一怒之下扔掉了刀鞘，武藏一击便将他打死。", highlight_en: ["carved from an oar"], highlight_zh: ["用船桨削成的木刀"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Musashi_(novel)" },
  { id: "naomi-s1", kind: "scene", book_id: "naomi", place_ids: ["jp-kaminarimon"], location: "Chapters 1–3", location_zh: "第一至三章", text_en: "Joji, a serious young engineer from a country family, finds a fifteen-year-old waitress named Naomi at the Café Diamond near the Kaminarimon and is struck by her Western look. He takes her into his care, rents a little Western-style house in Omori, and pays for her English and music lessons, meaning to raise her into the perfect modern wife. She grows into a beauty who takes lovers and makes him her slave.", text_zh: "让治是乡下人家出身、做事认真的年轻工程师，在雷门附近的钻石咖啡馆发现了一个十五岁的女招待奈绪美，被她西洋人般的长相吸引。他收留了她，在大森租下一座小洋房，供她学英语和音乐，想把她培养成完美的摩登妻子。她长成了一个美人，找了好几个情人，把他变成了自己的奴隶。", highlight_en: ["Café Diamond"], highlight_zh: ["钻石咖啡馆"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Naomi_(novel)" },
  { id: "izu-s1", kind: "scene", book_id: "izu-dancer", place_ids: ["jp-amagi-tunnel"], location: "Parts 1–3", location_zh: "第一至三节", text_en: "A twenty-year-old student, lonely and sour about himself, sets out to walk across the Izu Peninsula in autumn and falls in with a troupe of travelling players. In a teahouse at the pass the dancer Kaoru shyly gives him her cushion; at the hot springs he sees her wave to him naked from the bath, and laughs with relief, because she is still a child.", text_zh: "一个二十岁的学生孤独又自我厌弃，秋天独自徒步穿越伊豆半岛，和一班巡回艺人结伴同行。在山岭上的茶屋里，舞女熏子羞怯地把坐垫让给他；在温泉旅馆，他看见她赤身从浴池里朝他挥手，不禁松了口气笑起来——她还是个孩子。", highlight_en: ["travelling players"], highlight_zh: ["巡回艺人"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Dancing_Girl_of_Izu" },
  { id: "makioka-s1", kind: "scene", book_id: "makioka-sisters", place_ids: ["jp-ashiya-river"], location: "Book 2, Chapters 6–9", location_zh: "中卷第六至九章", text_en: "In July 1938 days of rain break into a flood that pours down from the Rokko mountains through Ashiya. Sachiko waits at home for news while the youngest sister, Taeko, is trapped at her sewing school as water and boulders fill the streets; the young photographer Itakura wades through the torrent and brings her out, which will tangle her life even further.", text_zh: "1938 年 7 月，连日大雨变成了洪水，从六甲山冲下，穿过芦屋。幸子在家里等消息，而最小的妹妹妙子被困在裁缝学校，街上满是洪水和巨石；年轻的摄影师板仓蹚过激流把她救了出来，这让她的人生更加纠缠不清。", highlight_en: ["flood"], highlight_zh: ["洪水"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Makioka_Sisters" },
  { id: "snow-s1", kind: "scene", book_id: "snow-country", place_ids: ["jp-takahan"], location: "Opening and ending", location_zh: "开头与结尾", text_en: "The train comes out of the long tunnel into the snow country. Shimamura, a dilettante from Tokyo, returns to the mountain hot spring to see Komako, a young geisha who loves him wholeheartedly though he gives her nothing. On his last night a cocoon warehouse used as a cinema catches fire; Yoko, the girl from the train, falls from its balcony, and as Shimamura looks up, the Milky Way seems to pour down into him.", text_zh: "火车穿过长长的隧道，就是雪国。东京来的闲人岛村又来到山中温泉看驹子——一个全心全意爱着他、而他什么也不给她的年轻艺伎。最后一夜，一座当作电影院的蚕茧仓库着了火，火车上遇见的姑娘叶子从楼上掉下来；岛村抬起头，银河仿佛向他倾泻下来。", highlight_en: ["Milky Way"], highlight_zh: ["银河"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Snow_Country" },
  { id: "setting-s1", kind: "scene", book_id: "setting-sun", place_ids: ["jp-shayokan"], location: "Chapters 1–8", location_zh: "第一至八章", text_en: "After the war, the aristocrat Kazuko and her frail mother sell their Tokyo house and move to a small villa in Izu, where the mother slowly fades. Her brother Naoji returns from the army addicted to drugs and kills himself, and Kazuko, deciding that 'man was born for love and revolution', sets out to have a child by the dissolute novelist Uehara and raise it alone.", text_zh: "战后，贵族小姐和子和体弱的母亲卖掉东京的房子，搬到伊豆的一座小别墅，母亲在那里慢慢衰弱下去。弟弟直治从军队回来后染上毒瘾，最终自杀；和子认定“人是为了爱和革命而生的”，决心和放荡的小说家上原生一个孩子，独自把他抚养长大。", highlight_en: ["love and revolution"], highlight_zh: ["爱和革命"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Setting_Sun" },
  { id: "golden-s1", kind: "scene", book_id: "golden-pavilion", place_ids: ["jp-kinkakuji"], location: "Chapters 1 and 10", location_zh: "第一章与第十章", text_en: "Mizoguchi, a stammering priest's son from the Japan Sea coast, has heard all his life that nothing on earth is as beautiful as the Golden Pavilion. As an acolyte there he finds its beauty stands between him and life, even between him and women. One night in 1950 he sets it on fire, means to die in the flames, then runs to the hills, throws away his knife and poison, and decides to live.", text_zh: "沟口是日本海边一个口吃的寺庙之子，从小就听父亲说世上没有比金阁更美的东西。他在金阁寺当了见习僧，却发现金阁的美横在他和生活之间，甚至横在他和女人之间。1950 年的一个夜里，他放火烧了金阁，本想死在火中，却跑上了山，扔掉了刀和毒药，决定活下去。", highlight_en: ["sets it on fire"], highlight_zh: ["放火烧了金阁"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Temple_of_the_Golden_Pavilion" },
  { id: "spring-s1", kind: "scene", book_id: "spring-snow", place_ids: ["jp-enshoji-nara"], location: "Chapters 49–54", location_zh: "第四十九至五十四章", text_en: "Kiyoaki, the beautiful son of a new noble family, has hidden his love for Satoko until she is engaged to an imperial prince; then they become lovers, and she is sent to take vows at the Gessho-ji convent near Nara. Already ill, he comes from Tokyo and climbs to the gate day after day through the February snow, and is refused each time. He dies in Tokyo at twenty.", text_zh: "清显是新贵族家的美少年，一直把对聪子的爱藏在心里，直到她和一位皇族订婚，两人才成了恋人；后来聪子被送进奈良附近的月修寺出家。已经生病的清显从东京赶来，冒着二月的大雪一天又一天爬到寺门前，每次都被拒绝。他回到东京后死去，年仅二十岁。", highlight_en: ["February snow"], highlight_zh: ["二月的大雪"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Spring_Snow" },
  { id: "hb-s1", kind: "scene", book_id: "hard-boiled-wonderland", place_ids: ["jp-waseda-murakami"], location: "Throughout", location_zh: "全书", text_en: "In alternating chapters, a data encoder in a near-future Tokyo is hired by an old scientist who has secretly wired a program into his brain, and pursued through the sewers beneath the city by sinister creatures; and in a walled Town at the End of the World, a newcomer whose shadow has been cut off reads old dreams from unicorn skulls. Slowly the two stories turn out to be one.", text_zh: "小说以单双章交替：在不远的未来的东京，一个“计算士”受雇于一位老科学家，对方暗中在他脑子里装了一段程序，他在城市地下的下水道里被险恶的怪物追赶；在一座有围墙的“世界尽头”小镇里，一个影子被剪掉的新来者从独角兽头骨里读取古老的梦。两个故事渐渐合而为一。", highlight_en: ["unicorn skulls"], highlight_zh: ["独角兽头骨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Hard-Boiled_Wonderland_and_the_End_of_the_World" },
  { id: "kasha-s1", kind: "scene", book_id: "all-she-was-worth", place_ids: ["jp-utsunomiya"], location: "Throughout", location_zh: "全书", text_en: "Honma, a Tokyo police inspector on leave after a shooting, agrees to find his nephew's fiancée, who vanished when a routine credit check revealed she had once gone bankrupt. Tracing her through Utsunomiya, Osaka and Nagoya, he finds that she was someone else: a woman crushed by her family's debts, who had taken over the identity of the real Shoko Sekine and perhaps killed her to do it.", text_zh: "东京刑警本间因枪伤休假，答应帮侄子寻找失踪的未婚妻——一次例行信用调查发现她曾经破产，她随即消失了。他一路追查到宇都宫、大阪和名古屋，发现她其实另有其人：一个被家里的债务压垮的女人，冒用了真正的关根彰子的身份，也许还为此杀了她。", highlight_en: ["Shoko Sekine"], highlight_zh: ["关根彰子"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/All_She_Was_Worth" },
  { id: "windup-s1", kind: "scene", book_id: "wind-up-bird", place_ids: ["jp-waseda-murakami"], location: "Book 1–2", location_zh: "第一至二部", text_en: "Toru Okada, out of work in a quiet Tokyo suburb, goes looking for his wife's lost cat and meets a string of strange women; then his wife Kumiko disappears too. An old officer tells him how he survived being thrown down a dry well in Mongolia in 1938, and Toru climbs down into the dry well of an abandoned house nearby and sits in the dark for days, searching for a way to her.", text_zh: "冈田亨在东京一个安静的郊区失了业，出门寻找妻子走失的猫，遇见一连串古怪的女人；接着，妻子久美子也失踪了。一位老军官讲起 1938 年他在蒙古被扔进一口枯井、竟活了下来的经历；于是亨爬进附近一座空宅的枯井，在黑暗里坐了好几天，寻找通向妻子的路。", highlight_en: ["dry well"], highlight_zh: ["枯井"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Wind-Up_Bird_Chronicle" },
  { id: "midnight-s1", kind: "scene", book_id: "journey-under-the-midnight-sun", place_ids: ["jp-osaka"], location: "Chapter 1", location_zh: "第一章", text_en: "In 1973 a pawnbroker is found stabbed in an abandoned building in Osaka. Detective Sasagaki suspects a poor widow who was his customer, but she and her lover die before anything can be proved, and the case goes cold. For the next nineteen years Sasagaki keeps watching two children touched by that day, the pawnbroker's son Ryoji and the widow's daughter Yukiho, as a trail of crimes follows them.", text_zh: "1973 年，大阪一栋废弃大楼里发现一个当铺老板被刺死。刑警笹垣怀疑他的一个顾客——一个穷寡妇，可她和她的情人在任何证据出现前都死了，案子成了悬案。此后十九年，笹垣一直盯着与那天有关的两个孩子：当铺老板的儿子亮司和寡妇的女儿雪穗，一连串罪案总是跟着他们。", highlight_en: ["abandoned building"], highlight_zh: ["废弃大楼"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Journey_Under_the_Midnight_Sun" },
  { id: "suspectx-s1", kind: "scene", book_id: "suspect-x", place_ids: ["jp-kiyosu-bridge"], location: "Chapters 1–2 and ending", location_zh: "第一至二章与结尾", text_en: "Ishigami, a brilliant mathematician reduced to teaching high school, walks to work each morning along the Sumida past the homeless men's shelters, and stops every day at the lunch shop where his neighbour Yasuko works. When she and her daughter kill her violent ex-husband, he takes charge, building them an alibi so perfect that only his old university friend, the physicist Yukawa, can see what it cost.", text_zh: "天才数学家石神沦落为高中老师，每天早上沿着隅田川步行上班，经过流浪汉的棚屋，每天都会去邻居靖子工作的便当店。靖子母女杀死了她施暴的前夫，石神接手了一切，为她们编了一个完美的不在场证明，只有他的大学老友、物理学家汤川看得出它付出的代价。", highlight_en: ["perfect"], highlight_zh: ["完美"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Devotion_of_Suspect_X" },
  { id: "1q84-s1", kind: "scene", book_id: "1q84", place_ids: ["jp-sangenjaya"], location: "Book 1, Chapter 1", location_zh: "第一部第一章", text_en: "Aomame, a fitness instructor who is also a hired killer, is late for an appointment and stuck in a taxi on the jammed Shuto Expressway, with Janacek's Sinfonietta on the radio. The driver tells her there is an emergency stairway down to the street nearby, and warns her that things may look different afterwards. She climbs down in her high heels, and soon notices that there are two moons in the sky.", text_zh: "健身教练青豆同时也是一名受雇的杀手。她赶着赴约，却被困在堵死的首都高速上的出租车里，收音机里放着雅纳切克的《小交响曲》。司机告诉她附近有一道下到地面的紧急楼梯，还提醒她，下去之后，事情可能看上去会不一样。她穿着高跟鞋爬了下去，不久便发现天上有两个月亮。", highlight_en: ["two moons"], highlight_zh: ["两个月亮"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/1Q84" },
  { id: "pm-s1", kind: "scene", book_id: "personal-matter", place_ids: ["jp-tokyo"], location: "Throughout", location_zh: "全书", text_en: "Bird, a twenty-seven-year-old crammer teacher who dreams of travelling in Africa, learns that his first son has been born with a brain hernia. Over the next days he drinks, hides with an old girlfriend and lets the doctors starve the baby, hoping it will die, until at last he turns back, takes the child from an abortion clinic and agrees to the operation that will save him.", text_zh: "二十七岁的补习班教师“鸟”梦想去非洲旅行，却得知第一个儿子生下来就有脑疝。接下来几天，他酗酒，躲在旧情人那里，任由医生不给婴儿喂奶，盼着孩子死去；最后他终于回头，把孩子从一家堕胎诊所抱回来，同意做那场能救他性命的手术。", highlight_en: ["brain hernia"], highlight_zh: ["脑疝"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Personal_Matter" },
  { id: "rain-s1", kind: "scene", book_id: "black-rain", place_ids: ["jp-genbaku-dome"], location: "Throughout", location_zh: "全书", text_en: "Years after the war, Shigematsu cannot find a husband for his niece Yasuko, because people say she has radiation sickness. To prove that she was not in the city that day, he copies out her diary and his own of August 1945: the flash, the march through burning streets, the dead in the river. But her diary records that on the way home a black rain fell on her, and she begins to sicken.", text_zh: "战后多年，重松一直给侄女矢须子找不到婆家，因为人们说她得了原子病。为了证明那天她不在市区，他把她和自己 1945 年 8 月的日记抄了一遍：闪光、穿过燃烧街道的跋涉、河里的尸体。可是她的日记里写着，回家路上一场黑雨落在了她身上，而她开始病倒了。", highlight_en: ["black rain"], highlight_zh: ["黑雨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Black_Rain_(novel)" },
  { id: "silence-s1", kind: "scene", book_id: "silence-endo", place_ids: ["jp-endo-museum"], location: "Chapters 1–8", location_zh: "第一至八章", text_en: "In 1639 the young Portuguese Jesuit Rodrigues lands secretly in Japan to find his old teacher Ferreira, said to have renounced the faith. Hidden by poor Christian villagers in Tomogi, then betrayed by the weak Kichijiro, he is made to watch believers drowned and hung in pits, until he is told that if he steps on a bronze image of Christ they will be saved, and he hears a voice telling him to trample.", text_zh: "1639 年，年轻的葡萄牙耶稣会士罗德里格偷偷登上日本，寻找据说已经弃教的老师费雷拉。他先被友木村贫穷的基督徒藏起来，后来被软弱的吉次郎出卖，被迫看着信徒们被溺死、被倒吊在坑里，直到有人告诉他：只要他踩一下铜制的基督像，他们就能得救。这时他听见一个声音叫他踩下去。", highlight_en: ["bronze image of Christ"], highlight_zh: ["铜制的基督像"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Silence_(End%C5%8D_novel)" },
  { id: "silentcry-s1", kind: "scene", book_id: "silent-cry", place_ids: ["jp-uchiko"], location: "Throughout", location_zh: "全书", text_en: "After a friend's suicide and the birth of a disabled son, Mitsusaburo goes back with his wife and his brother Takashi to the family house in a forest valley in Shikoku. Takashi organises the village youths into a football team and then leads them in looting the supermarket owned by a Korean 'emperor', re-enacting the peasant rising led by their great-grandfather's brother in 1860.", text_zh: "朋友自杀、残障儿子出生之后，蜜三郎和妻子、弟弟鹰四一起回到四国森林山谷里的老家。鹰四把村里的年轻人组织成一支足球队，然后带着他们抢了“超市天皇”——一个朝鲜人老板——的超市，重演了 1860 年他们曾祖父的弟弟领导的农民起义。", highlight_en: ["football team"], highlight_zh: ["足球队"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Silent_Cry" },
  { id: "fireflies-s1", kind: "scene", book_id: "grave-of-the-fireflies", place_ids: ["jp-hotaru-monument"], location: "Throughout", location_zh: "全篇", text_en: "After their mother dies in the firebombing of Kobe in June 1945, fourteen-year-old Seita takes his four-year-old sister Setsuko to an aunt in Nishinomiya, who soon resents them. They move into a dugout shelter by a pond, light it with fireflies they catch, and live on what Seita can steal, until Setsuko dies of malnutrition; a month later Seita dies at Sannomiya station.", text_zh: "1945 年 6 月，母亲死于神户大空袭，十四岁的清太带着四岁的妹妹节子投奔西宫的姑妈，没多久就遭了嫌弃。他们搬进池塘边的防空洞，用捉来的萤火虫照明，靠清太偷来的东西度日，直到节子营养不良而死；一个月后，清太也死在了三宫车站。", highlight_en: ["fireflies"], highlight_zh: ["萤火虫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Grave_of_the_Fireflies_(short_story)" },
  { id: "shogun-s1", kind: "scene", book_id: "shogun", place_ids: ["jp-adams-memorial"], location: "Book 1", location_zh: "第一卷", text_en: "In 1600 the English pilot John Blackthorne is shipwrecked with his starving crew at the fishing village of Anjiro and thrown into a pit by the local samurai. Brought before the great lord Toranaga, he learns Japanese ways with the help of his Christian interpreter Mariko, becomes a samurai, and is caught up in the struggle that will make Toranaga shogun.", text_zh: "1600 年，英国领航员约翰·布莱克索恩和饥饿的船员在渔村安治劳遇难，被当地武士扔进地坑。他被带到大名虎长面前，在信基督教的翻译真理子帮助下学习日本的规矩，成了武士，卷进了一场将让虎长成为将军的权力斗争。", highlight_en: ["shipwrecked"], highlight_zh: ["遇难"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Sh%C5%8Dgun_(novel)" },
  { id: "hiroshima-s1", kind: "scene", book_id: "hiroshima-hersey", place_ids: ["jp-shukkeien"], location: "'The Fire' and 'Details Are Being Investigated'", location_zh: "《大火》《细节正在调查》", text_en: "Hersey follows six survivors through 6 August 1945 and the days after. In the afternoon hundreds of burned and dying people crowd into Asano Park by the river; the Reverend Tanimoto finds a punt and ferries the wounded across, wading with them in the tide, while Father Kleinsorge fetches water in a kettle for those who cannot move.", text_zh: "赫西跟随六名幸存者，写下 1945 年 8 月 6 日和此后的日子。那天下午，数百名烧伤、垂死的人挤进河边的浅野泉邸；谷本牧师找到一条平底船，把伤员渡过河，自己在潮水里蹚着；克莱因佐格神父则用水壶为动不了的人打水。", highlight_en: ["Asano Park"], highlight_zh: ["浅野泉邸"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Hiroshima_(book)" },
  { id: "geisha-s1", kind: "scene", book_id: "memoirs-of-a-geisha", place_ids: ["jp-gion"], location: "Chapters 1–8", location_zh: "第一至八章", text_en: "Nine-year-old Chiyo, from the fishing village of Yoroido, is sold to an okiya in Gion and made a maid, bullied by the jealous geisha Hatsumomo. One day, weeping by the Shirakawa stream after a failed escape, she is comforted by a kind gentleman, the Chairman, who buys her a shaved ice and gives her his handkerchief, and she decides to become a geisha so she can meet him again.", text_zh: "九岁的千代来自渔村养老町，被卖到祇园的置屋当女佣，受尽善妒的艺伎初桃欺凌。一天，逃跑失败的她在白川边哭泣，一位好心的绅士——“会长”——安慰了她，给她买了一碗刨冰，还把手帕送给她。她于是决心当上艺伎，好再见到他。", highlight_en: ["shaved ice"], highlight_zh: ["刨冰"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Memoirs_of_a_Geisha" },
  { id: "samurai-s1", kind: "scene", book_id: "samurais-garden", place_ids: ["jp-tarumi"], location: "Throughout", location_zh: "全书", text_en: "Stephen, a twenty-year-old Chinese art student ill with tuberculosis, is sent in 1937 to his family's summer house in the seaside village of Tarumi. Cared for by Matsu, the silent old caretaker, he slowly learns his secret: Matsu has for decades loved Sachi, a woman with leprosy who lives in the mountain colony of Yamaguchi, while news comes of Japan's war on China.", text_zh: "二十岁的中国美术学生斯蒂芬患了肺结核，1937 年被送到家里在海边垂水村的避暑别墅。他由沉默的老管家松照顾，慢慢知道了松的秘密：几十年来，松一直爱着住在山里麻风病人村山口的女子佐知；与此同时，日本侵华的消息不断传来。", highlight_en: ["Tarumi"], highlight_zh: ["垂水"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Samurai%27s_Garden" },
  { id: "pachinko-s1", kind: "scene", book_id: "pachinko", place_ids: ["jp-tsuruhashi"], location: "Book 1–2", location_zh: "第一至二部", text_en: "Sunja, a lodging-house keeper's daughter in Busan, is pregnant by a married fish broker when a sickly young minister, Isak, marries her and takes her to Osaka in 1933. They live among Koreans in the crowded, pig-keeping slum of Ikaino, despised by the Japanese; when Isak is jailed, Sunja and her sister-in-law sell kimchi and sweets on the street to keep the family alive.", text_zh: "釜山客栈老板的女儿顺子怀了一个有妇之夫——鱼贩汉洙——的孩子，体弱的年轻牧师以撒娶了她，1933 年带她到了大阪。他们住在猪饲野拥挤、养猪的贫民窟，和朝鲜人挤在一起，受日本人歧视；以撒入狱后，顺子和妯娌在街头卖泡菜和糖果，养活了一家人。", highlight_en: ["Ikaino"], highlight_zh: ["猪饲野"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Pachinko_(novel)" },
  { id: "zoet-s1", kind: "scene", book_id: "jacob-de-zoet", place_ids: ["jp-dejima"], location: "Parts 1–2", location_zh: "第一至二部", text_en: "In 1799 the pious young Dutch clerk Jacob de Zoet arrives at Dejima to root out corruption and make his fortune, and falls for Orito Aibagawa, a Japanese midwife with a burned face who has been allowed to study with the Dutch doctor. When she is taken to a mountain shrine whose monks keep a terrible secret, Jacob, confined to his tiny island, can do nothing to save her.", text_zh: "1799 年，虔诚的年轻荷兰文书雅各布·德佐特来到出岛，打算整肃腐败、发一笔财，却爱上了脸上有烧伤疤痕的日本助产士蓝场川织斗——她获准跟荷兰医生学医。后来她被带进一座山中神社，那里的僧人守着一个可怕的秘密，而被困在小岛上的雅各布无力救她。", highlight_en: ["Orito"], highlight_zh: ["织斗"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Thousand_Autumns_of_Jacob_de_Zoet" },
  // —— 11-22 quotations from Aozora Bunko, replacing the placeholder scene notes (add_jp3.py) ——
  { id: "kojiki-1", book_id: "kojiki", place_ids: ["jp-izumo-taisha"], location: "Book 1, 'The Ceding of the Land'", location_zh: "上卷《让国》", text_orig: "ここに答へ白さく、「僕が子ども二神の白せるまにまに、僕も違はじ。この葦原の中つ國は、命のまにまに既に獻りぬ。ただ僕が住所は、天つ神の御子の天つ日繼知らしめさむ、富足る天の御巣の如、底つ石根に宮柱太しり、高天の原に氷木高しりて治めたまはば、僕は百足らず八十坰手に隱りて侍はむ。また僕が子ども百八十神は八重事代主の神を御尾前として仕へまつらば、違ふ神はあらじ」と、かく白して出雲の國の多藝志の小濱に、天の御舍を造りて…", highlight_orig: ["出雲の國の多藝志の小濱"], text_en: "Then he answered: 'As my two sons have said, so I too will not go against it. This Central Land of the Reed Plains I have already yielded at your command. Only let my dwelling be like the rich heavenly abode from which the august child of the heavenly gods will rule the heavenly succession, its pillars planted firm on the bedrock below and its roof-beams raised high to the Plain of High Heaven; then I will withdraw and wait in the eighty winding corners of the land. And if my hundred and eighty children serve with Yae-kotoshironushi going before them and behind, not one god will disobey.' So he said, and on the little beach of Tagishi in the land of Izumo a heavenly hall was built…", highlight_en: ["the little beach of Tagishi in the land of Izumo"], text_zh: "于是大国主神答道：“我的两个儿子怎么说，我也不违背。这苇原中国，已经遵命献上了。只求我的住处，能像天神之子继承天位时所居的丰足天宫那样，宫柱稳稳扎在地底的磐石上，屋脊的木梁高高伸到高天原；这样，我便退到弯弯曲曲的八十个角落里侍候。我那一百八十个儿子，若由八重事代主神在前后带领着侍奉，就不会有违抗的神。”说完，便在出云国多艺志的小滨，造起了天上的宫殿……", highlight_zh: ["出云国多艺志的小滨"], translation: "own", status: "draft", checked: "Aozora Bunko #51731 (ruby and the editor's note numbers left out), 2026-11-22" },
  { id: "tosa-1", book_id: "tosa-diary", place_ids: ["jp-tosa-kokubunji"], location: "Opening, the 21st day of the 12th month", location_zh: "开篇，十二月二十一日", text_orig: "男もすなる日記といふものを、女もしてみむとてするなり。それの年（承平四年）のしはすの二十日あまり一日の、戌の時に門出す。そのよしいさゝかものにかきつく。ある人縣の四年五年はてゝ例のことゞも皆しをへて、解由など取りて住むたちより出でゝ船に乘るべき所へわたる。", highlight_orig: ["住むたち"], text_en: "Diaries are things that men keep, I hear; I, a woman, will try my hand at one too. In a certain year (the fourth of Shohei), on the twenty-first day of the twelfth month, at the hour of the Dog, we set out. I note down a little of how it went. A certain person, his four or five years in the province over, the customary business all done and his release papers in hand, left the residence where he had lived and crossed to the place where he was to board the boat.", highlight_en: ["the residence where he had lived"], text_zh: "听说日记这东西是男人写的，我这个女人也想写写看。某年（承平四年）十二月二十一日戌时，动身出发。把经过略略记在这里。有一个人，在这个国任满了四五年，照例的事务都办完了，拿到了解由状，从住了多年的官舍出来，到要上船的地方去。", highlight_zh: ["住了多年的官舍"], translation: "own", status: "draft", checked: "Aozora Bunko #832, 2026-11-22" },
  { id: "hojoki-1", book_id: "hojoki", place_ids: ["jp-shimogamo"], location: "Opening", location_zh: "开篇", text_orig: "行く川のながれは絶えずして、しかも本の水にあらず。よどみに浮ぶうたかたは、かつ消えかつ結びて久しくとゞまることなし。世の中にある人とすみかと、またかくの如し。", highlight_orig: ["行く川"], text_en: "The flowing river never ceases, and yet its water is never the same water. The foam that floats on its still pools now vanishes, now forms again, and never stays for long. So it is with the people of this world and their dwellings.", highlight_en: ["The flowing river"], text_zh: "流去的河水从不断绝，却已不是原来的水。浮在河湾里的泡沫，时而消散，时而凝聚，从不久留。世上的人和他们的住处，也是这样。", highlight_zh: ["流去的河水"], translation: "own", status: "draft", checked: "Aozora Bunko #975, 2026-11-22" },
  { id: "oku-1", book_id: "oku-no-hosomichi", place_ids: ["jp-takadachi"], location: "Hiraizumi", location_zh: "《平泉》", text_orig: "三代の榮耀一睡の中にして、大門の跡は一里こなたに有。秀衡が跡は田野に成て、金鷄山のみ形を殘す。先高舘にのぼれば、北上川南部より流るゝ大河也。衣川は和泉が城をめぐりて、高舘の下にて大河に落入。康衡等が旧跡は、衣が關を隔て南部口をさし堅め、夷をふせぐとみえたり。偖も義臣すぐつて此城にこもり、功名一時の叢となる。「國破れて山河あり、城春にして草青みたり」と笠打敷て時のうつるまで泪を落し侍りぬ。\n夏草や兵どもが夢の跡", highlight_orig: ["高舘"], text_en: "The glory of three generations passed in a single sleep; the site of the great gate lies a league this side of here. Where Hidehira's palace stood are fields now, and only Mount Kinkei keeps its shape. First we climbed to Takadachi: below it runs the Kitakami, a great river flowing down from Nanbu. The Koromo river circles Izumi's castle and falls into the great river beneath Takadachi. The old stronghold of Yasuhira and his men lay beyond the Koromo barrier, guarding the way in from Nanbu, it seems, and holding off the northern tribes. And so the chosen loyal men shut themselves in this castle, and their glory became, in a moment, a stretch of grass. 'The state is broken, the mountains and rivers remain; the castle in spring is green with grass,' I recited, and sat on my hat and wept until the time had passed.\nThe summer grass: all that is left of warriors' dreams.", highlight_en: ["Takadachi"], text_zh: "三代的荣华，一梦之间便成空；大门的遗迹在一里之外。秀衡的旧居已成田野，只有金鸡山还留着原样。先登上高馆，只见北上川是从南部流来的大河。衣川绕过和泉的城，在高馆下面汇入大河。泰衡等人的旧迹，隔着衣关，扼守南部的入口，看来是为了防御夷人。想当年，精选的忠臣据守这座城，一时的功名，化作了一片草丛。“国破山河在，城春草青青”，我铺下斗笠坐着，流泪直到时光推移。\n夏草啊，武士们的梦的遗迹。", highlight_zh: ["高馆"], translation: "own", status: "draft", checked: "Aozora Bunko #61619 (ruby and the editor's note numbers left out), 2026-11-22" },
  { id: "ugetsu-1", book_id: "ugetsu-monogatari", place_ids: ["jp-kibitsu"], location: "'The Kibitsu Cauldron'", location_zh: "《吉备津之釜》", text_orig: "猶幸を神に祈るとて、巫子祝部を召しあつめて、御湯をたてまつる。そもそも当社に祈誓する人は、数の祓物を供へて御湯を奉り、吉祥凶祥を占ふ。巫子祝詞をはり、湯の沸上るにおよびて、吉祥には釜の鳴る音牛の吼ゆるが如し。凶きは釜に音なし。是を吉備津の御釜祓といふ。さるに香央が家の事は、神の祈けさせ給はぬにや、只秋の虫の叢にすだくばかりの声もなし。", highlight_orig: ["吉備津の御釜祓"], text_en: "To pray to the god for still more good fortune, they gathered the shrine maidens and priests and offered the sacred hot water. Whoever makes a vow at this shrine offers many purification gifts and the sacred hot water, and so divines good fortune or ill. When the maidens have finished the prayers and the water comes to the boil, for good fortune the cauldron roars like a lowing ox; for ill, the cauldron makes no sound. This is called the Cauldron Purification of Kibitsu. But for Kasada's house, as if the god would not hear the prayer, there was not even as much sound as autumn insects make chirping in the grass.", highlight_en: ["the Cauldron Purification of Kibitsu"], text_zh: "为了再向神祈福，他们召来巫女和神官，献上御汤。凡是到这座神社许愿的人，都要供上许多祓物，献上御汤，占卜吉凶。巫女念完祝词，等到汤沸起来，若是吉兆，釜就发出像牛吼一样的声音；若是凶兆，釜便没有声音。这叫做吉备津的御釜祓。可是轮到香央家的事，神像是不肯听这祈愿，连秋虫在草丛里鸣叫那么一点声音都没有。", highlight_zh: ["吉备津的御釜祓"], translation: "own", status: "draft", checked: "Aozora Bunko #60608 (ruby and the editor's note numbers left out), 2026-11-22" },
  { id: "takekurabe-1", book_id: "takekurabe", place_ids: ["jp-ichiyo-museum"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "廻れば大門の見返り柳いと長けれど、お歯ぐろ溝に燈火うつる三階の騒ぎも手に取る如く、明けくれなしの車の行来にはかり知られぬ全盛をうらなひて、大音寺前と名は仏くさけれど、さりとは陽気の町と住みたる人の申き…", highlight_orig: ["大音寺前"], text_en: "Go round, and the long Mikaeri willow at the great gate is still far off, yet the revelry of the three-storey houses, their lamps reflected in the black-tooth ditch, seems close enough to touch, and from the rickshaws coming and going day and night you can guess at a prosperity beyond counting. Daionji-mae, they call it, a name that smells of the temple, but it is a lively quarter all the same, said someone who lived there…", highlight_en: ["Daionji-mae"], text_zh: "绕过去，大门口的回首柳还远，可是映在黑齿沟里的灯火、三层楼上的喧闹，却近得仿佛伸手可及；从昼夜不停来来往往的车子，就能想见那数不清的繁华。“大音寺前”，名字带着佛气，住在这里的人却说，这其实是个热闹的地方……", highlight_zh: ["大音寺前"], translation: "own", status: "draft", checked: "Aozora Bunko #56041, 2026-11-22" },
  { id: "kokoro-1", book_id: "kokoro", place_ids: ["jp-yuigahama"], location: "Part 1, 'Sensei and I', Chapter 1", location_zh: "上篇《先生与我》第一节", text_orig: "私が先生と知り合いになったのは鎌倉である。その時私はまだ若々しい書生であった。\n…\n私は毎日海へはいりに出掛けた。古い燻ぶり返った藁葺の間を通り抜けて磯へ下りると、この辺にこれほどの都会人種が住んでいるかと思うほど、避暑に来た男や女で砂の上が動いていた。ある時は海の中が銭湯のように黒い頭でごちゃごちゃしている事もあった。", highlight_orig: ["鎌倉"], text_en: "It was at Kamakura that I came to know Sensei. I was still a young student then.\n…\nEvery day I went down to swim in the sea. When I had passed between the old, smoke-blackened thatched roofs and come down to the shore, the sand was alive with men and women here to escape the heat, so many that you wondered whether so many city people really lived in these parts. Some days the sea itself was as crowded with black heads as a public bath.", highlight_en: ["Kamakura"], text_zh: "我和先生相识，是在镰仓。那时我还是个年轻的学生。\n…\n我每天都去海里游泳。穿过那些熏得发黑的旧茅草屋顶走到海边，只见沙滩上挤满了来避暑的男男女女，多得让人怀疑这一带竟住着这么多城里人。有时候，海里黑压压的人头挤成一片，像澡堂一样。", highlight_zh: ["镰仓"], translation: "own", status: "draft", checked: "Aozora Bunko #773, 2026-11-22" },
  { id: "hakai-1", book_id: "broken-commandment", place_ids: ["jp-iiyama"], location: "Chapter 1, section 1", location_zh: "第一章第一节", text_orig: "蓮華寺では下宿を兼ねた。瀬川丑松が急に転宿を思ひ立つて、借りることにした部屋といふのは、其蔵裏つゞきにある二階の角のところ。寺は信州下水内郡飯山町二十何ヶ寺の一つ、真宗に附属する古刹で、丁度其二階の窓に倚凭つて眺めると、銀杏の大木を経てゝ飯山の町の一部分も見える。さすが信州第一の仏教の地、古代を眼前に見るやうな小都会、奇異な北国風の屋造、板葺の屋根、または冬期の雪除として使用する特別の軒庇から、ところ〲に高く顕れた寺院と樹木の梢まで――すべて旧めかしい町の光景が香の烟の中に包まれて見える。たゞ一際目立つて此窓から望まれるものと言へば、現に丑松が奉職して居る其小学校の白く塗つた建築物であつた。", highlight_orig: ["飯山町", "飯山の町"], text_en: "The Rengeji temple took in lodgers. The room Segawa Ushimatsu had suddenly decided to move into, and had taken, was at the corner of the upper floor, next to the storehouse. The temple, one of the twenty-odd temples of the town of Iiyama in the Shimominochi district of Shinshu, was an old foundation of the Shin sect; leaning on the sill of that upstairs window you could see, past a great ginkgo, a part of the town of Iiyama. It was, after all, the chief seat of Buddhism in Shinshu, a little town where the past seemed to stand before your eyes: the strange northern houses, the shingled roofs, the deep eaves built to keep off the winter snow, and here and there, rising high, the temples and the tops of trees, the whole old-fashioned town seemed wrapped in incense smoke. The one thing that stood out from this window was the white-painted building of the primary school where Ushimatsu now taught.", highlight_en: ["Iiyama"], text_zh: "莲华寺兼营寄宿。濑川丑松突然想搬家，租下的那间屋子，在紧挨着库房的二楼拐角。这座寺是信州下水内郡饭山町二十几座寺院中的一座，是属于真宗的古刹；倚在那二楼的窗口眺望，隔着一棵大银杏树，还能看见饭山町的一角。不愧是信州第一的佛教之地，一座仿佛让人亲眼看见古代的小城：奇特的北国式房屋、木板铺的屋顶、冬天挡雪用的特制深檐，还有处处高高露出的寺院和树梢——整个古旧的街景都像笼罩在香烟里。从这扇窗望出去，唯一特别显眼的，就是丑松现在任教的那所小学刷成白色的校舍。", highlight_zh: ["饭山町"], translation: "own", status: "draft", checked: "Aozora Bunko #1502, 2026-11-22" },
  { id: "koya-1", book_id: "koya-hijiri", place_ids: ["jp-amo-pass"], location: "Section 1", location_zh: "第一节", text_orig: "「参謀本部編纂の地図をまた繰開いて見るでもなかろう、と思ったけれども、余りの道じゃから、手を触るさえ暑くるしい、旅の法衣の袖をかかげて、表紙を附けた折本になってるのを引張り出した。\n飛騨から信州へ越える深山の間道で、ちょうど立休らおうという一本の樹立も無い、右も左も山ばかりじゃ、手を伸ばすと達きそうな峰があると、その峰へ峰が乗り、巓が被さって、飛ぶ鳥も見えず、雲の形も見えぬ。\n道と空との間にただ一人我ばかり、およそ正午と覚しい極熱の太陽の色も白いほどに冴え返った光線を、深々と戴いた一重の檜笠に凌いで、こう図面を見た。」", highlight_orig: ["飛騨から信州へ越える深山の間道"], text_en: "'I thought there was no point in opening the General Staff's map again, but the road was so bad that, though it was stifling even to touch it, I lifted the sleeve of my travelling robe and pulled out the folding map in its covers.\nIt was a byway through the deep mountains, crossing from Hida into Shinshu. There was not a single tree to stop and rest under; to right and left there was nothing but mountains. Where a peak stood so near it seemed you could reach out and touch it, peak rode upon peak and summit lay over summit; not a bird could be seen flying, not even the shape of a cloud.\nBetween the road and the sky there was only I, alone. Shielding myself under my deep, single-layer cypress hat from the glare of a sun that must have been near noon, so fierce that its very colour had gone white, I looked at the map like this.'", highlight_en: ["a byway through the deep mountains, crossing from Hida into Shinshu"], text_zh: "“我本想，那参谋本部编的地图也不必再翻开看了，可路实在太难走，连手碰一碰都觉得闷热，我还是撩起旅途法衣的袖子，把那本带封皮的折页地图抽了出来。\n那是从飞驒翻往信州的深山小道，连一棵可以站下歇歇的树都没有，左右全是山；眼看伸手就够得着的山峰上面，又压着一座座山峰，山顶叠着山顶，看不见飞鸟，也看不见云的影子。\n路和天之间，只有我一个人。大约正午时分，酷热的太阳亮得发白，我把单层的桧木斗笠压得深深的，挡着那光，就这样看着地图。”", highlight_zh: ["从飞驒翻往信州的深山小道"], translation: "own", status: "draft", checked: "Aozora Bunko #521, 2026-11-22" },
  { id: "kani-1", book_id: "crab-cannery-ship", place_ids: ["jp-hakodate-port"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "「おい地獄さ行ぐんだで！」\n二人はデッキの手すりに寄りかかって、蝸牛が背のびをしたように延びて、海を抱え込んでいる函館の街を見ていた。", highlight_orig: ["函館の街"], text_en: "'Hey, we're off to hell!'\nThe two of them leaned on the deck rail, looking at the town of Hakodate, stretched out like a snail craning its neck, its arms around the sea.", highlight_en: ["the town of Hakodate"], text_zh: "“喂，咱们这是下地狱去啦！”\n两个人靠在甲板的栏杆上，望着函馆的街市——它像蜗牛伸长了身子那样延展开去，把海抱在怀里。", highlight_zh: ["函馆的街市"], translation: "own", status: "draft", checked: "Aozora Bunko #1465, 2026-11-22" },
  { id: "rashomon-1", book_id: "rashomon", place_ids: ["jp-rajomon"], location: "Opening", location_zh: "开篇", text_orig: "ある日の暮方の事である。一人の下人が、羅生門の下で雨やみを待っていた。\n広い門の下には、この男のほかに誰もいない。ただ、所々丹塗の剥げた、大きな円柱に、蟋蟀が一匹とまっている。羅生門が、朱雀大路にある以上は、この男のほかにも、雨やみをする市女笠や揉烏帽子が、もう二三人はありそうなものである。それが、この男のほかには誰もいない。", highlight_orig: ["羅生門"], text_en: "It was one evening, towards dusk. A servant was waiting under the Rashomon for the rain to stop.\nUnder the wide gate there was no one but this man. Only, on a great round pillar whose red lacquer had peeled away here and there, a single cricket was clinging. Since the Rashomon stands on Suzaku Avenue, you would think that besides this man there would be two or three others sheltering from the rain, women in broad sedge hats, men in soft lacquered caps. Yet there was no one but this man.", highlight_en: ["Rashomon"], text_zh: "那是一天傍晚的事。一个家仆在罗生门下等雨停。\n宽阔的门下，除了这个人，再没有别人。只有一根朱漆斑驳的大圆柱上，停着一只蟋蟀。罗生门既然在朱雀大路上，除了这个人，总该还有两三个戴市女笠、戴揉乌帽子的人在这里避雨才是。可是，除了这个人，一个人也没有。", highlight_zh: ["罗生门"], translation: "own", status: "draft", checked: "Aozora Bunko #127, 2026-11-22" },
  { id: "fugaku-1", book_id: "fugaku-hyakkei", place_ids: ["jp-misaka-pass"], location: "The stay at Misaka Pass", location_zh: "御坂峠一段", text_orig: "御坂峠、海抜千三百米。この峠の頂上に、天下茶屋といふ、小さい茶店があつて、井伏鱒二氏が初夏のころから、ここの二階に、こもつて仕事をして居られる。私は、それを知つてここへ来た。\n…\nこの峠は、甲府から東海道に出る鎌倉往還の衝に当つてゐて、北面富士の代表観望台であると言はれ、ここから見た富士は、むかしから富士三景の一つにかぞへられてゐるのださうであるが、私は、あまり好かなかつた。好かないばかりか、軽蔑さへした。あまりに、おあつらひむきの富士である。まんなかに富士があつて、その下に河口湖が白く寒々とひろがり、近景の山々がその両袖にひつそり蹲つて湖を抱きかかへるやうにしてゐる。私は、ひとめ見て、狼狽し、顔を赤らめた。これは、まるで、風呂屋のペンキ画だ。芝居の書割だ。どうにも註文どほりの景色で、私は、恥づかしくてならなかつた。", highlight_orig: ["御坂峠", "天下茶屋"], text_en: "Misaka Pass, thirteen hundred metres above the sea. At the top of the pass there is a little teahouse called the Tenka Chaya, and since early summer Mr Ibuse Masuji had shut himself away upstairs there to work. I knew this, and that is why I came.\n…\nThis pass sits at a crossing of the Kamakura road that runs from Kofu out to the Tokaido, and is said to be the finest place to view Fuji from the north; Fuji seen from here has long been counted one of the three great views of the mountain. I did not much like it. Worse than not liking it, I despised it. It was a Fuji made to order: Fuji in the middle, Lake Kawaguchi spread white and cold beneath it, and the near hills crouching quietly at either side as if holding the lake in their arms. At one look I was flustered and blushed. It was just like a painting on a bathhouse wall. A stage backdrop. A view so exactly as ordered that I could not bear the shame of it.", highlight_en: ["Misaka Pass", "Tenka Chaya"], text_zh: "御坂峠，海拔一千三百米。峠顶上有一家叫天下茶屋的小茶店，井伏鳟二先生从初夏起就闷在这里的二楼写作。我知道这件事，才来到这里。\n…\n这座山口正当从甲府通往东海道的镰仓往还要冲，据说是从北面观赏富士最好的地方，从这里看见的富士，自古就被算作富士三景之一。可我不怎么喜欢。不只是不喜欢，甚至瞧不起。这富士也太像定做的了：富士在正中，下面河口湖白茫茫、冷清清地铺开，近处的山静静地蹲在两侧，像是把湖抱在怀里。我一看，就慌了，脸都红了。这简直是澡堂墙上的油漆画，是戏台上的布景。完全照着订单做出来的风景，我羞得受不了。", highlight_zh: ["御坂峠", "天下茶屋"], translation: "own", status: "draft", checked: "Aozora Bunko #270, 2026-11-22" },
  { id: "nlh-1", book_id: "no-longer-human", place_ids: ["jp-shayokan"], location: "The First Notebook", location_zh: "第一手记", text_orig: "恥の多い生涯を送って来ました。\n自分には、人間の生活というものが、見当つかないのです。自分は東北の田舎に生れましたので、汽車をはじめて見たのは、よほど大きくなってからでした。", highlight_orig: ["東北の田舎"], text_en: "Mine has been a life of much shame.\nI have never been able to make out what human life is. I was born in the countryside of the northeast, and it was not until I was quite big that I saw a train for the first time.", highlight_en: ["the countryside of the northeast"], text_zh: "我这一生，尽是可耻的事。\n我对人的生活，一点也摸不着头脑。我生在东北的乡下，第一次看见火车，已经是长得很大以后的事了。", highlight_zh: ["东北的乡下"], translation: "own", status: "draft", checked: "Aozora Bunko #301, 2026-11-22" },
  // —— 11-22 quotations from Japanese Wikisource, replacing the placeholder scene notes (add_jp4.py) ——
  { id: "manyo-1", book_id: "manyoshu", place_ids: ["jp-amanokagu"], location: "Book 1, poem 13", location_zh: "卷一第 13 首", text_orig: "香具山は　畝傍を善しと　耳成と　相争ひき\n神代より　かくなるらし　古昔も　しかなれこそ\n現身も　嬬を　争ふらしき", highlight_orig: ["香具山"], text_en: "Mount Kagu, finding Unebi fair,\nquarrelled with Miminashi over her.\nSince the age of the gods, it seems, it has been so;\nand since it was so in ancient days,\nwe in this mortal world too,\nit seems, must quarrel over a wife.", highlight_en: ["Mount Kagu"], text_zh: "香具山看中了亩傍山，\n同耳成山相争。\n自神代以来，似乎就是这样；\n古时既然如此，\n如今世上的人\n也要为妻子相争吧。", highlight_zh: ["香具山"], translation: "own", status: "draft", checked: "Japanese Wikisource, 万葉集 (鹿持雅澄訓訂)/巻第一 (the editor's poem number left out), 2026-11-22" },
  { id: "manyo-2", book_id: "manyoshu", place_ids: ["jp-amanokagu"], location: "Book 1, poem 28", location_zh: "卷一第 28 首", text_orig: "春過ぎて夏来るらし白布の衣乾したり天の香具山", highlight_orig: ["天の香具山"], text_en: "Spring has passed, and summer, it seems, has come:\nwhite robes are spread to dry\non heavenly Mount Kagu.", highlight_en: ["heavenly Mount Kagu"], text_zh: "春天过去，夏天似乎来了：\n天之香具山上，\n晾着雪白的衣裳。", highlight_zh: ["天之香具山"], translation: "own", status: "draft", checked: "Japanese Wikisource, 万葉集 (鹿持雅澄訓訂)/巻第一, 2026-11-22" },
  { id: "taketori-1", book_id: "taketori", place_ids: ["jp-fuji-summit"], location: "Ending", location_zh: "结尾", text_orig: "勅使には調岩笠といふ人を召して、駿河の國にあンなる山の巓にもて行くべきよし仰せ給ふ。峰にてすべきやう教へさせたもふ。御文・不死の藥の壺ならべて、火をつけてもやすべきよし仰せ給ふ。そのよし承りて、兵士どもあまた具して山へ登りけるよりなん、その山をふしの山とは名づけゝる。その煙いまだ雲の中へたち昇るとぞいひ傳へたる。", highlight_orig: ["ふしの山"], text_en: "As his envoy he summoned a man named Tsuki no Iwakasa, and ordered him to take them to the summit of the mountain in the land of Suruga. He had him taught what was to be done on the peak: to set the letter and the jar of the elixir of immortality side by side, put fire to them and burn them. The envoy took the order and climbed the mountain with a great many soldiers, and from that time, it is said, the mountain has been called Fuji, rich in soldiers. Its smoke, the story goes, still rises into the clouds.", highlight_en: ["Fuji"], text_zh: "他召来一个名叫调岩笠的人做敕使，命他把这些带到骏河国那座山的山顶上去，又叫人教他在峰顶该怎样做：把书信和不死药的药壶并排放好，点火烧掉。敕使领了旨，带着许多兵士登上山去；从那以后，这座山就叫做富士山。据说那烟至今还升入云中。", highlight_zh: ["富士山"], translation: "own", status: "draft", checked: "Japanese Wikisource, 竹取物語 (國民文庫) (the editor's sic mark left out), 2026-11-22" },
  { id: "ise-1", book_id: "tales-of-ise", place_ids: ["jp-yatsuhashi"], location: "Episode 9", location_zh: "第九段", text_orig: "もとよりともする人。ひとりふたりして。もろともにゆきけり。みちしれる人もなくて。まどひゆきけり。みかはのくにやつはしといふ所にいたりぬ。そこやつはしといふことは。水のくもでにながれわかれて。木八わたせるによりてなむ八橋とはいへる。その澤のほとりに。木かげにおりゐて。かれいひくひけり。その澤にかきつばたいとおもしろくさきたり。それを見て。都いとこひしくおぼえけり。さりけれぱある人。かきつばたといふいつもじを。くのかしらにすへて。たひの心よめといひければ。ひとの人よめり。\nから衣きつゝなれにしつましあれは遙々きぬる旅をしそ思\nと讀りければ。みな人かれいひのうへに淚落してほとびにけり。", highlight_orig: ["やつはし", "八橋"], text_en: "One or two who had always been his companions went along with him. With no one who knew the way, they went on, losing it, and came to a place called Yatsuhashi in the land of Mikawa. It is called Yatsuhashi, Eight Bridges, because the water there branches out like a spider's legs and eight planks are laid across it. They got down in the shade of the trees by that marsh and ate their dried rice. In the marsh the irises were blooming beautifully. Seeing them, he longed for the capital. So one of them said, 'Make a poem on the feelings of the journey, with the five syllables ka-ki-tsu-ba-ta at the heads of its lines,' and he made this:\nI have a wife, familiar as the robe from Kara I have worn so long,\nand so I think how far I have come on this journey.\nWhen he had said it, everyone wept onto their dried rice until it swelled.", highlight_en: ["Yatsuhashi"], text_zh: "一向同行的朋友有一两个，便一起去了。没有认得路的人，一路走一路迷路，来到三河国一个叫八桥的地方。所以叫八桥，是因为那里的水像蜘蛛的脚一样分流开去，上面架了八座木桥。他们在那片沼泽边的树荫下下马坐着，吃干饭。沼泽里燕子花开得正好。看见了，他非常想念京城。于是有人说：“把‘燕子花’（かきつばた）这五个音放在每句的开头，咏一首旅途的心情吧。”他便咏道：\n唐衣穿久了贴身，妻子也这样与我亲近；\n远远地来到这里，不禁想起这趟旅途。\n他一吟完，大家的眼泪都落在干饭上，把饭泡软了。", highlight_zh: ["八桥"], translation: "own", status: "draft", checked: "Japanese Wikisource, 伊勢物語 (群書類從), 2026-11-22" },
  { id: "pillow-1", book_id: "pillow-book", place_ids: ["jp-kyoto-gosho"], location: "'The snow of Xianglu Peak'", location_zh: "《香炉峰之雪》", text_orig: "雪いと高く降りたるを例ならず御格子まゐらせて、す櫃に火起して物語などして集まり侍ふに「少納言よ香爐峰の雪はいかならむ」と仰せられければ、御格子あげさせて、御簾高く卷き上げたれば、笑はせたまふ。人々も皆さる事は知り、歌などにさへうたへど、思ひこそよらざりつれ。「なほこの宮の人にはさるべきなめり」といふ。", highlight_orig: ["この宮"], text_en: "The snow had fallen very deep, and, which was unusual, the lattice shutters had been let down; we had made up a fire in the brazier and were gathered round it talking, when Her Majesty said, 'Shonagon, how is the snow on Xianglu Peak?' I had the shutters raised and rolled the blind up high, and she laughed. The others all knew the lines and had even put them into songs, but it had not occurred to them. 'Someone in this palace,' they said, 'ought to be just like that.'", highlight_en: ["this palace"], text_zh: "雪下得很深，难得地放下了格子窗，在火盆里生了火，大家聚在一起说话。这时中宫说：“少纳言，香炉峰的雪怎么样了？”我叫人把格子窗打开，把帘子高高卷起，中宫便笑了。别的人也都知道这句诗，甚至还唱进歌里，却没有想到这一层。她们说：“这宫里的人，就该是这样吧。”", highlight_zh: ["这宫里"], translation: "own", status: "draft", checked: "Japanese Wikisource, 枕草紙 (國文大觀), 2026-11-22" },
  { id: "genji-1", book_id: "tale-of-genji", place_ids: ["jp-uji-bridge"], location: "'The Drifting Boat'", location_zh: "《浮舟》", text_orig: "山の方は霞隔てて、寒き洲崎に立てる鵲の姿も、所からはいとをかしう見ゆるに、宇治橋のはるばると見わたさるるに、柴積み舟の所々に行きちがひたるなど、他にて目馴れぬことどものみとり集めたる所なれば、見たまふたびごとに、なほそのかみのことのただ今の心地して、いとかからぬ人を見交はしたらむだに、めづらしき仲のあはれ多かるべきほどなり。\n…\n「宇治橋の長き契りは朽ちせじを\n危ぶむ方に心騒ぐな\n今見たまひてむ」\nとのたまふ。\n「絶え間のみ世には危ふき宇治橋を\n朽ちせぬものとなほ頼めとや」", highlight_orig: ["宇治橋"], text_en: "Toward the hills the haze hung between, and even a magpie standing on the cold sandspit looked lovely, as things do in such a place; Uji Bridge could be seen stretching far into the distance, and boats loaded with brushwood passed one another here and there. It was a place that gathered together nothing but sights unlike any one grew used to elsewhere, so that each time he looked at it the past came back as if it were now; even with a woman who had no such ties to it, such a meeting would have been full of rare feeling.\n…\n'Long as Uji Bridge,\nour pledge will never rot away:\ndo not let your heart race in fear that it will fall.\nYou will see soon enough,'\nhe said.\n'Uji Bridge, so full of gaps,\nalways so unsafe in this world,\nand you still ask me to trust it will not rot?'", highlight_en: ["Uji Bridge"], text_zh: "山那边隔着一层霞，寒冷的沙洲上立着的喜鹊，因了这个地方，也显得格外有趣；宇治桥远远地望得见，运柴的船这里那里往来交错——这里聚集的尽是别处看不惯的景致，所以他每次看见，往事都像眼前的事一样；即使对面是与这里毫无因缘的人，这样难得的相会也该有许多感慨。\n…\n“宇治桥长，我们的盟约，\n永远不会朽坏：\n莫要担心它断，心慌意乱。\n不久你就会明白。”\n他这样说。\n“宇治桥上处处断缺，\n世上最是危险，\n你还要我相信它不会朽坏吗？”", highlight_zh: ["宇治桥"], translation: "own", status: "draft", checked: "Japanese Wikisource, 源氏物語 (渋谷栄一校訂)/浮舟, 2026-11-22" },
  { id: "sarashina-1", book_id: "sarashina-diary", place_ids: ["jp-kazusa-kokubunji"], location: "Opening", location_zh: "开篇", text_orig: "東路の道のはてよりも、なほ奧つかたに生ひ出たる人、いかばかりかはあやしかりけむを、いかに思ひ始めけることにか、世中に物語といふもののあなるを、いかで見ばやと思ひつゝ、徒然なるひるまよひゐなどに、姉、繼母などやうの人々の、その物語かの物語、光源氏のあるやうなど、ところ〴〵語るを聞くに、いとゞゆかしさまされど、我が思ふまゝに、そらにいかでか覺え語らむ。", highlight_orig: ["東路の道のはて"], text_en: "Brought up somewhere even further off than the far end of the road to the east, how countrified I must have been! Yet somehow, I cannot think how it began, I came to hear that there were such things in the world as tales, and longed to read them; in idle daytimes and evenings my sister, my stepmother and the others would tell bits of this tale and that, and of how the Shining Genji lived, and hearing them only made me long for more. But how could they tell them from memory just as I wished?", highlight_en: ["the far end of the road to the east"], text_zh: "我生长在比东路的尽头还要更远的地方，那时该是多么土气啊。可不知怎么起了念头，听说世上有“物语”这种东西，就一心想看看。闲来无事的白天和夜晚，姐姐、继母她们讲这个物语、那个物语，讲光源氏怎样怎样，零零碎碎的，我听了更想看了；可她们凭记忆，又怎能照我的心意讲给我听呢。", highlight_zh: ["东路的尽头"], translation: "own", status: "draft", checked: "Japanese Wikisource, 更級日記 (有朋堂文庫) (the editor's gloss 〔源氏物語〕 left out), 2026-11-22" },
  { id: "tsure-1", book_id: "tsurezuregusa", place_ids: ["jp-ninnaji"], location: "Section 52", location_zh: "第五十二段", text_orig: "仁和寺にある法師、年よるまで石淸水ををがまざりければ、心うくおぼえて、ある時思ひたちて、たゞ一人かちよりまうでけり。極樂寺高良などを拜みて、かばかりと心得てかへりにけり。さて傍の人に逢ひて、「年ごろ思ひつる事はたし侍りぬ。聞きしにもすぎてたふとくこそおはしけれ。そも參りたる人ごとに山へのぼりしは、何事かありけむ、ゆかしかりしかど、神へまゐるこそほいなれと思ひて、山までは見ず」とぞいひける。すこしの事にも、先達はあらまほしきことなり。", highlight_orig: ["仁和寺"], text_en: "A monk of Ninna-ji, ashamed that he had grown old without ever worshipping at Iwashimizu, made up his mind one day and went there alone, on foot. He worshipped at Gokuraku-ji, the Kora shrine and the rest, decided that was all, and came home. Then, meeting one of his fellows, he said: 'I have done at last what I had meant to do for years. It was even holier than I had heard. Though I did wonder what was up there, since everyone who went was climbing the hill; I wanted to see, but I thought, it is the god I came to worship, and did not go up the hill.' Even in small things, a guide is to be wished for.", highlight_en: ["Ninna-ji"], text_zh: "仁和寺有个法师，到老还没拜过石清水，心里觉得惭愧，有一天下了决心，独自一人步行前去。拜了极乐寺、高良社这些地方，以为就是这些了，便回来了。后来他见了同伴，说：“多年的心愿总算了了。比听说的还要庄严。只是去参拜的人个个都往山上爬，不知上面有什么，我很想看看，可又想，来拜神才是本意，就没上山去看。”哪怕是小事，也最好有个引路的人。", highlight_zh: ["仁和寺"], translation: "own", status: "draft", checked: "Japanese Wikisource, 徒然草 (國文大觀), 2026-11-22" },
  // —— 11-23: fifth pack (tools/content/batches/add_jp5.py) ——
  { id: "botchan-1", book_id: "botchan", place_ids: ["jp-dogo"], location: "Chapter 3", location_zh: "第三章", text_orig: "この住田と云う所は温泉のある町で城下から汽車だと十分ばかり、歩いて三十分で行かれる、料理屋も温泉宿も、公園もある上に遊廓がある。", highlight_orig: ["住田と云う所は温泉のある町"], text_en: "This place called Sumita is a hot-spring town, ten minutes or so from the castle town by train and thirty on foot, with restaurants and hot-spring inns and a park, and a licensed quarter on top of that.", highlight_en: ["Sumita is a hot-spring town"], text_zh: "这个叫住田的地方是个温泉町，从城下坐火车十来分钟，走路三十分钟就到，有饭馆，有温泉旅店，有公园，此外还有花街。", highlight_zh: ["住田的地方是个温泉町"], translation: "own", status: "draft", checked: "Japanese Wikisource, 坊つちやん, 2026-11-23" },
  { id: "sanshiro-1", book_id: "sanshiro", place_ids: ["jp-sanshiro-pond"], location: "Chapter 2", location_zh: "第二章", text_orig: "三四郎がじっとして池の面を見つめていると、大きな木が、幾本となく水の底に映って、そのまた底に青い空が見える。三四郎はこの時電車よりも、東京よりも、日本よりも、遠くかつはるかな心持ちがした。", highlight_orig: ["池の面"], text_en: "As Sanshiro sat still, gazing at the surface of the pond, he saw any number of great trees reflected in the depths of the water, and deeper still the blue sky. At that moment he felt far away, farther than the trams, farther than Tokyo, farther than Japan.", highlight_en: ["the surface of the pond"], text_zh: "三四郎一动不动地凝视着池面，只见许多大树倒映在水底，再往下还能看见蓝天。这一刻，三四郎觉得自己离得很远很远，比电车远，比东京远，比日本还远。", highlight_zh: ["池面"], translation: "own", status: "draft", checked: "Japanese Wikisource, 三四郎, 2026-11-23" },
  { id: "kusamakura-1", book_id: "kusamakura", place_ids: ["jp-oama"], location: "Opening", location_zh: "开头", text_orig: "山路を登りながら、こう考えた。\n智に働けば角が立つ。情に棹させば流される。意地を通せば窮屈だ。とかくに人の世は住みにくい。", highlight_orig: ["山路"], text_en: "Climbing the mountain path, I thought:\nWork by reason, and you grow sharp-edged. Pole along the stream of feeling, and you are swept away. Insist on your own will, and you are cramped. In short, this world of men is a hard place to live.", highlight_en: ["the mountain path"], text_zh: "一边登着山路，一边这样想：\n凭理智行事，就会棱角毕露；顺着感情撑篙，就会被水冲走；固执己见，又处处受窘。总之，人世是难住的。", highlight_zh: ["山路"], translation: "own", status: "draft", checked: "Japanese Wikisource, 草枕 (the indent of a line dropped), 2026-11-23" },
  { id: "takasebune-1", book_id: "takasebune", place_ids: ["jp-takase"], location: "Opening", location_zh: "开头", text_orig: "高瀬舟は京都の高瀬川を上下する小舟である。徳川時代に京都の罪人が遠島を申し渡されると、本人の親類が牢屋敷へ呼び出されて、そこで暇乞をすることを許された。それから罪人は高瀬舟に載せられて、大阪へ廻されることであつた。", highlight_orig: ["京都の高瀬川"], text_en: "A Takase boat is a small boat that goes up and down the Takase River in Kyoto. In the Tokugawa period, when a criminal of Kyoto was sentenced to exile on a distant island, his relatives were summoned to the jail and allowed to take leave of him there. Then the criminal was put on a Takase boat and sent round to Osaka.", highlight_en: ["the Takase River in Kyoto"], text_zh: "高濑舟是在京都高濑川上来往的小船。德川时代，京都的罪人被判流放远岛之后，他的亲属会被叫到牢房，获准在那里同他诀别。然后罪人就被送上高濑舟，押往大阪。", highlight_zh: ["京都高濑川"], translation: "own", status: "draft", checked: "Japanese Wikisource, 高瀬舟, 2026-11-23" },
  { id: "oku-yamadera", book_id: "oku-no-hosomichi", place_ids: ["jp-yamadera"], location: "Risshaku-ji", location_zh: "立石寺", text_orig: "山形領に立石寺といふ山寺あり慈覺大師の開基にして殊に勝閑の地なり一見すべきよし人々のすゝむるによつて尾花澤より取てかへし其間七里許なり日いまだくれず麓の坊に宿かり置て山上の堂に登る岩に巖を重て山とし松柏年ふり土石老てこけなめらかに岩上の院に扉を閉て物の音聞へず岸をめぐり岩を這て佛閣を拜し佳景寂寞として心すみ行のみ覺ゆ\n閑さや岩にしみ込せみの聲", highlight_orig: ["立石寺"], text_en: "In the domain of Yamagata there is a mountain temple called Risshaku-ji, founded by the Great Teacher Jikaku, a place of rare purity and stillness. People urged us to see it, so we turned back from Obanazawa, a distance of some seven leagues. It was still light. We took lodgings at a priest's house at the foot and climbed to the halls on the mountain. Rock is piled on boulder to make the hill, the pines and cypresses are old, the earth and stones are aged and smooth with moss, and the doors of the halls on the rocks were shut, with not a sound to be heard. We went round the cliff and crept over the rocks to worship at the Buddha hall, and in the lovely scene and the silence I felt only my heart growing clear.\nThe stillness:\nsinking into the rocks,\nthe cicadas' cry.", highlight_en: ["Risshaku-ji"], text_zh: "山形领内有一座山寺，叫立石寺，是慈觉大师开创的，格外清静。人们都劝我们去看一看，于是从尾花泽折回去，其间约有七里。天色尚早，先在山脚的僧坊订好住处，然后登上山上的佛堂。岩上叠岩成山，松柏苍老，土石古旧，青苔滑润；岩上各院的门扉紧闭，听不到一点声响。绕过崖边，爬过岩石，参拜了佛阁，只觉得佳景寂寞，心也澄净下来。\n寂静啊，\n渗入岩石里的\n蝉声。", highlight_zh: ["立石寺"], translation: "own", status: "draft", checked: "Japanese Wikisource, おくのほそ道 (the indent of a line dropped) (this edition prints the poem as しみ込, 'sinking in'), 2026-11-23" },
  { id: "oku-matsushima", book_id: "oku-no-hosomichi", place_ids: ["jp-matsushima"], location: "Matsushima", location_zh: "松岛", text_orig: "抑事ふりにたれど松島は扶桑第一の好風にして凡洞庭西湖をはぢず東南より海入て江の中三里浙江の潮をたゝゆ島々の數を盡して欹ものは天を指ふすものは波に圃匐あるは二重にかさなり三重にたゝみて左にわかれ右に連る負るあり抱あり兒孫を愛するがごとし", highlight_orig: ["松島"], text_en: "It has been said many times before, but Matsushima is the finest scenery in all Japan, and need not blush before Dongting or the West Lake. The sea comes in from the south-east and fills a bay three leagues across, brimming like the tide of Zhejiang. Islands beyond counting: those that rise point to the sky, those that lie low crawl upon the waves. Some are piled in two layers, some folded in three; they part to the left and join to the right. Some carry others on their backs, some hold them in their arms, as if fondling children and grandchildren.", highlight_en: ["Matsushima"], text_zh: "这话早已被人说旧了，可松岛实在是扶桑第一的好风景，决不逊于洞庭、西湖。海水从东南涌入，湾内三里，满盈如浙江之潮。岛屿不可胜数：耸立的直指青天，低伏的匍匐波上；有的叠作两层，有的折成三重，左边分开，右边相连；有的背着，有的抱着，好像在疼爱儿孙。", highlight_zh: ["松岛"], translation: "own", status: "draft", checked: "Japanese Wikisource, おくのほそ道, 2026-11-23" },
  { id: "oku-sado", book_id: "oku-no-hosomichi", place_ids: ["jp-izumozaki"], location: "Echigo", location_zh: "越后路", text_orig: "あら海や佐渡に橫たふ天河", highlight_orig: ["佐渡"], text_en: "The rough sea:\nstretching out over Sado,\nthe River of Heaven.", highlight_en: ["Sado"], text_zh: "汹涌的海啊，\n横卧在佐渡之上的\n银河。", highlight_zh: ["佐渡"], translation: "own", status: "draft", checked: "Japanese Wikisource, おくのほそ道, 2026-11-23" },
  { id: "takuboku-1", book_id: "a-handful-of-sand", place_ids: ["jp-shibutami"], location: "'Smoke', part 2", location_zh: "《烟》之二", text_orig: "ふるさとの山に向ひて\n言ふことなし\nふるさとの山はありがたきかな", highlight_orig: ["ふるさとの山"], text_en: "Facing the mountain of my home\nI have nothing to say.\nThe mountain of my home: how thankful I am for it.", highlight_en: ["mountain of my home"], text_zh: "面对故乡的山，\n无话可说，\n故乡的山，真叫人感激啊。", highlight_zh: ["故乡的山"], translation: "own", status: "draft", checked: "Japanese Wikisource, 一握の砂, 2026-11-23" },
  { id: "yoake-1", book_id: "before-the-dawn", place_ids: ["jp-magome"], location: "Part 1, prologue", location_zh: "第一部序章", text_orig: "木曾路はすべて山の中である。あるところは岨づたいに行く崖の道であり、あるところは数十間の深さに臨む木曾川の岸であり、あるところは山の尾をめぐる谷の入り口である。一筋の街道はこの深い森林地帯を貫いていた。", highlight_orig: ["木曾路"], text_en: "The Kiso road lies entirely among the mountains. In one place it is a path along a cliff, clinging to the precipice; in another it is the bank of the Kiso river, many tens of yards above the water; in another it is the entrance to a valley, rounding the tail of a mountain. A single highway ran through this deep forest country.", highlight_en: ["The Kiso road"], text_zh: "木曾路全在山里。有的地方是贴着峭壁走的崖道，有的地方是下临数十间深的木曾川岸，有的地方是绕过山尾的谷口。一条大道贯穿着这片幽深的森林地带。", highlight_zh: ["木曾路"], translation: "own", status: "draft", checked: "Japanese Wikisource, 夜明け前/第一部上, 2026-11-23" },
  { id: "konjiki-1", book_id: "konjiki-yasha", place_ids: ["jp-atami"], location: "Part 1, chapter 8", location_zh: "前编第八章", text_orig: "一月の十七日、宮さん、善く覚えてお置き。来年の今月今夜は、貫一は何処でこの月を見るのだか！　再来年の今月今夜……十年後の今月今夜……一生を通して僕は今月今夜を忘れん、忘れるものか、死んでも僕は忘れんよ！", highlight_orig: ["今月今夜"], text_en: "The seventeenth of January, Miya: remember it well. Next year, on this night of this month, where will Kan'ichi be looking at this moon! The year after, on this night of this month… ten years from now, on this night of this month… all my life I shall not forget this night of this month. How could I forget it? Even dead I shall not forget!", highlight_en: ["this night of this month"], text_zh: "一月十七日，阿宫，你好好记住。明年的今月今夜，贯一会在什么地方看这个月亮呢！后年的今月今夜……十年后的今月今夜……我一辈子也忘不了今月今夜，怎么忘得了，就是死了我也忘不了！", highlight_zh: ["今月今夜"], translation: "own", status: "draft", checked: "Japanese Wikisource, 金色夜叉, 2026-11-23" },
  { id: "kokoro-zo1", book_id: "kokoro", place_ids: ["jp-zoshigaya"], location: "Part 1, chapter 4", location_zh: "上篇第四节", text_orig: "先生は例月その日になると雑司ヶ谷の墓地にある或る仏へ花を手向けに行く習慣なのだそうである。", highlight_orig: ["雑司ヶ谷の墓地"], text_en: "Every month on that day, I was told, Sensei was in the habit of going to lay flowers at a certain grave in the cemetery at Zoshigaya.", highlight_en: ["the cemetery at Zoshigaya"], text_zh: "据说先生有个习惯，每月到了那一天，都要去杂司谷墓地给某位故人献花。", highlight_zh: ["杂司谷墓地"], translation: "own", status: "draft", checked: "Japanese Wikisource, こころ, 2026-11-23" },
  { id: "genji-suma1", book_id: "tale-of-genji", place_ids: ["jp-suma"], location: "Chapter 12, 'Suma'", location_zh: "第十二帖《须磨》", text_orig: "須磨には、いとど心尽くしの秋風に、海はすこし遠けれど、行平中納言の、「関吹き越ゆる」と言ひけむ浦波、夜々はげにいと近く聞こえて、またなくあはれなるものは、かかる所の秋なりけり。", highlight_orig: ["須磨"], text_en: "At Suma the autumn wind brought ever deeper melancholy; the sea was some way off, but the waves of the bay, of which the counsellor Yukihira once sang that the wind 'blows across the barrier', sounded very near indeed night after night, and nothing could be more moving than autumn in such a place.", highlight_en: ["Suma"], text_zh: "须磨这地方，秋风越发叫人愁肠百转。海虽然离得稍远，但行平中纳言吟咏过“越关吹来”的那片海湾的波涛，夜夜听来却近在耳边；再没有什么比这种地方的秋天更令人感伤的了。", highlight_zh: ["须磨"], translation: "own", status: "draft", checked: "Japanese Wikisource, 源氏物語/須磨, 2026-11-23" },
  { id: "manyo-ume1", book_id: "manyoshu", place_ids: ["jp-dazaifu"], location: "Book 5, preface to the thirty-two plum-blossom poems", location_zh: "卷五《梅花歌三十二首》序", text_orig: "天平二年正月の十三日、帥の老の宅に萃ひて、宴会を申ぶ。時に初春の令月、気淑く風和ぐ。梅は鏡前の粉を披き、蘭は珮後の香を薫らす。", highlight_orig: ["帥の老の宅"], text_en: "On the thirteenth day of the first month of the second year of Tenpyo we gathered at the residence of the old Governor-General and held a banquet. It was the fair month of early spring; the air was fresh and the wind gentle. The plum blossoms opened like powder before a mirror, and the orchids breathed the fragrance of a sachet.", highlight_en: ["the residence of the old Governor-General"], text_zh: "天平二年正月十三日，聚集在帅老的宅邸，开宴会。时值初春令月，气淑风和；梅花绽开，如镜前的脂粉，兰草吐香，如佩后的香囊。", highlight_zh: ["帅老的宅邸"], translation: "own", status: "draft", checked: "Japanese Wikisource, 万葉集 (鹿持雅澄訓訂)/巻第五, 2026-11-23" },
  { id: "loti-1", book_id: "madame-chrysantheme", place_ids: ["jp-inasa"], location: "Chapter 2", location_zh: "第二章", text_orig: "Quand Nagasaki parut, ce fut une déception pour nos yeux : au pied des vertes montagnes surplombantes, c’était une ville tout à fait quelconque.", highlight_orig: ["Nagasaki"], text_en: "When Nagasaki came into view, it was a disappointment to our eyes: at the foot of the green overhanging mountains, it was a town of the most ordinary kind.", highlight_en: ["Nagasaki"], text_zh: "等到长崎出现在眼前，我们的眼睛却失望了：在高悬的青山脚下，它不过是一座再平常不过的城市。", highlight_zh: ["长崎"], translation: "own", status: "draft", checked: "French Wikisource, Madame Chrysanthème, 1899/02 (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "bird-nikko1", book_id: "unbeaten-tracks-in-japan", place_ids: ["jp-nikko"], location: "Letter VII", location_zh: "第七封信", text_en: "Kanaya is the chief man in the village, and is very intelligent and apparently well educated.\n…\nOf late, to help his income, he has let these charming rooms to foreigners who have brought letters to him, and he is very anxious to meet their views, while his good taste leads him to avoid Europeanising his beautiful home.", highlight_en: ["Kanaya"], translation: "original", text_zh: "金谷是村里的头面人物，很聪明，看得出受过良好教育。\n…\n近来为了贴补收入，他把这些可爱的房间租给带着介绍信来的外国人；他很想让客人满意，而他的好品味又使他不肯把自己美丽的家弄得洋里洋气。", highlight_zh: ["金谷"], status: "draft", checked: "English Wikisource, Unbeaten Tracks in Japan/LETTER VII (a gap marked …), 2026-11-23" },
  { id: "kappa-s1", kind: "scene", book_id: "kappa-akutagawa", place_ids: ["jp-kappabashi"], location: "Chapters 1–2", location_zh: "第一、二章", text_en: "Patient No. 23 of a mental hospital tells anyone who will listen how, three summers ago, he set out alone from the hot-spring inn at Kamikochi to climb Mount Hotaka. In the mist by the Azusa river he saw a kappa looking at him, chased it through the bamboo grass, fell into a hole, and woke up in the country of the kappas.", text_zh: "某精神病院的第二十三号病人逢人便讲：三年前的夏天，他独自从上高地的温泉旅馆出发去登穗高山。在梓川边的雾里，他看见一只河童正望着自己，便穿过山白竹丛追上去，掉进一个洞里，醒来已经到了河童的国度。", highlight_en: ["Kamikochi"], highlight_zh: ["上高地"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Kappa_(novella)" },
  { id: "kinosaki-s1", kind: "scene", book_id: "at-kinosaki", place_ids: ["jp-kinosaki"], location: "The whole story", location_zh: "全篇", text_en: "Convalescing alone at the hot spring after an accident that might have killed him, the narrator watches three small deaths: a bee lying still on the roof outside his window, a rat with a skewer through its neck being stoned as it swims the stream, and a newt he kills himself with a carelessly thrown pebble. Being alive and being dead come to seem to him not so far apart.", text_zh: "叙述者在一场险些丧命的事故之后，独自到温泉疗养，目睹了三次微小的死亡：窗外屋顶上一动不动的蜜蜂，脖子上穿着竹签、在小河里挣扎着被人扔石头的老鼠，还有被他自己随手扔出的石子打死的蝾螈。他渐渐觉得，活着和死去并不是相隔多远的两回事。", highlight_en: ["the hot spring"], highlight_zh: ["温泉"], status: "draft", fact_source: "https://ja.wikipedia.org/wiki/城の崎にて" },
  { id: "koto-s1", kind: "scene", book_id: "the-old-capital", place_ids: ["jp-heian"], location: "Chapter 1, 'The Flowers of Spring'", location_zh: "第一章《春花》", text_en: "Chieko, the adopted daughter of a kimono wholesaler, goes with her childhood friend Shin'ichi to see the weeping cherries in the garden of the Heian Shrine, and under the blossoms tells him she was a foundling. Later that year, at the Gion festival, she will meet a girl from the cedar village in the northern hills who has her own face.", text_zh: "和服批发商的养女千重子同青梅竹马的真一去平安神宫的神苑看红枝垂樱，在花下告诉他自己是个弃儿。这一年稍后的祇园祭上，她将遇见一个来自北山杉村、长着同她一模一样面孔的姑娘。", highlight_en: ["the Heian Shrine"], highlight_zh: ["平安神宫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Old_Capital" },
  { id: "shiosai-s1", kind: "scene", book_id: "sound-of-waves", place_ids: ["jp-kamishima"], location: "Chapter 8", location_zh: "第八章", text_en: "Shinji, a poor young fisherman, and Hatsue, the daughter of the richest man on the island, shelter from a storm in the ruined observation post on the hill. They dry their clothes on either side of a fire, and she tells him to jump across it to her. The island's gossip does the rest, until Shinji proves himself in a typhoon at sea.", text_zh: "穷苦的年轻渔夫新治和岛上首富的女儿初江，在山上废弃的监视哨里躲避暴风雨。两人隔着一堆火烘干衣服，她叫他从火上跳过来。此后岛上流言四起，直到新治在海上的台风中证明了自己。", highlight_en: ["the ruined observation post"], highlight_zh: ["废弃的监视哨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Sound_of_Waves" },
  { id: "tsugaru-s1", kind: "scene", book_id: "tsugaru", place_ids: ["jp-kodomari"], location: "Chapter 5, 'The West Coast'", location_zh: "第五章《西海岸》", text_en: "On the last day of his journey Dazai takes the bus to Kodomari to find Take, the nursemaid he has not seen for nearly thirty years. Her house is locked: the whole village is at the school sports day. He walks round the crowded field until a girl leads him to her, and the two sit side by side watching the races, hardly speaking.", text_zh: "旅行的最后一天，太宰坐公共汽车到小泊去找阿竹——将近三十年没见面的保姆。她家锁着门：全村人都去看学校的运动会了。他在拥挤的操场上转来转去，直到一个女孩把他领到她跟前；两人并肩坐着看赛跑，几乎没说话。", highlight_en: ["Kodomari"], highlight_zh: ["小泊"], status: "draft", fact_source: "https://ja.wikipedia.org/wiki/津軽_(小説)" },
  { id: "tempyo-s1", kind: "scene", book_id: "roof-tile-of-tempyo", place_ids: ["jp-toshodaiji"], location: "The whole novel", location_zh: "全书", text_en: "In 733 young monks sail for Tang China with the embassy, Yoei and Fusho among them, charged to bring back a master who can ordain priests properly. Of the others, one wanders off into the country and one settles there; Yoei dies in the south; the old monk Gyogo, who has spent his life copying sutras, goes down with his manuscripts on the voyage home. Only Fusho stays the course, and twenty years later lands in Japan with the old, blind Jianzhen.", text_zh: "733 年，荣叡、普照等几个年轻僧人随遣唐使船前往唐土，奉命请回一位能如法传戒的高僧。其余的人，一个云游四方，一个留在了那里；荣叡死在南方；抄了一辈子经的老僧业行，在归国途中连同经卷一起沉入海底。只有普照坚持到底，二十年后同年老失明的鉴真一起踏上日本的土地。", highlight_en: ["Jianzhen"], highlight_zh: ["鉴真"], status: "draft", fact_source: "https://ja.wikipedia.org/wiki/天平の甍" },
  { id: "ryoma-s1", kind: "scene", book_id: "ryoma-ga-yuku", place_ids: ["jp-katsurahama"], location: "The whole novel", location_zh: "全书", text_en: "The youngest son of a merchant-samurai family of Kochi, a late bloomer whom nobody expected much of, leaves Tosa for a fencing school in Edo in the year the American ships arrive. Over the next fourteen years he flees his domain, founds a trading company with a navy of its own, reconciles Satsuma and Choshu, and is cut down in Kyoto a month after the shogun resigns.", text_zh: "高知一个商人出身的乡士家里的小儿子，开窍很晚，谁也没指望他有什么出息；就在美国军舰到来的那一年，他离开土佐去江户的剑术道场。此后十四年里，他脱藩出走，办起一家自带海军的商社，撮合了萨摩和长州，又在将军交还大政一个月后在京都遇刺。", highlight_en: ["Kochi"], highlight_zh: ["高知"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Ryōma_ga_Yuku" },
  { id: "ten-s1", kind: "scene", book_id: "points-and-lines", place_ids: ["jp-kashii"], location: "Chapters 1–4", location_zh: "第一至四章", text_en: "On a January morning a ministry official and a waitress from a Tokyo restaurant are found lying side by side on the shore at Kashii, poisoned with cyanide: to all appearances a lovers' suicide. An old Fukuoka detective is bothered by a dining-car receipt for one. The case comes to turn on the four minutes a day in which one platform of Tokyo Station can be seen from another.", text_zh: "一月的一个早晨，某部的一名官员和东京一家餐馆的女招待被发现并排躺在香椎的海岸上，死于氰化物中毒——怎么看都是殉情。福冈的一位老刑警却对一张只有一人份的餐车收据放心不下。案子最后的关键，是东京站一天之中只有四分钟能从一个站台望见另一个站台。", highlight_en: ["the shore at Kashii"], highlight_zh: ["香椎的海岸"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Points_and_Lines" },
  { id: "kafka-s1", kind: "scene", book_id: "kafka-on-the-shore", place_ids: ["jp-takamatsu"], location: "Chapters 1–7", location_zh: "第一至七章", text_en: "On his fifteenth birthday a boy who calls himself Kafka Tamura leaves his father's house in Tokyo and takes the night bus to Takamatsu, for no better reason than that Shikoku is far away and warm. He spends his days in a small private library kept by an elegant woman and a young assistant, and is taken in there.", text_zh: "一个自称田村卡夫卡的少年在十五岁生日那天离开东京父亲的家，坐夜行巴士去了高松，理由不过是四国够远，也够暖和。他每天泡在一座小小的私人图书馆里，图书馆由一位优雅的女士和一个年轻馆员打理，后来他就被收留在那里。", highlight_en: ["Takamatsu"], highlight_zh: ["高松"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Kafka_on_the_Shore" },
  { id: "heike-yashima", kind: "scene", book_id: "tale-of-the-heike", place_ids: ["jp-yashima"], location: "Book 11, 'Nasu no Yoichi'", location_zh: "卷十一《那须与一》", text_en: "At dusk, with the fighting broken off, a boat puts out from the Heike fleet with a fan fixed to a pole and a lady beckoning beside it. Yoshitsune orders the young archer Nasu no Yoichi to shoot. He rides into the sea, prays, and looses; the fan flies up and falls into the waves, and both sides beat their quivers and the sides of their ships in applause.", text_zh: "黄昏时分，战斗暂歇，平家船队里划出一条小船，竿头插着一把扇子，旁边一位女官招手示意。义经命令年轻的射手那须与一去射。他策马走进海里，祈祷之后放箭；扇子飞上半空，落进波浪，两军一齐敲着箭筒和船舷喝彩。", highlight_en: ["the Heike fleet"], highlight_zh: ["平家船队"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Nasu_no_Yoichi" },
  { id: "hyoten-s1", kind: "scene", book_id: "freezing-point", place_ids: ["jp-miura"], location: "The whole novel", location_zh: "全书", text_en: "While the doctor's wife is entertaining an admirer, their small daughter wanders out and is strangled by the river beyond the wood. To punish his wife, the doctor secretly adopts a baby girl he believes to be the murderer's daughter and lets her bring the child up as her own. The girl, Yoko, grows up loved by everyone, until the wife finds his diary.", text_zh: "医生的妻子在家里接待一位爱慕者的时候，年幼的女儿独自跑了出去，在树林那边的河滩上被人掐死。为了惩罚妻子，医生瞒着她收养了一个他以为是凶手女儿的女婴，让她当作亲生女儿抚养。这个叫阳子的女孩在人人疼爱中长大，直到妻子发现了丈夫的日记。", highlight_en: ["the wood"], highlight_zh: ["树林"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Freezing_Point_(novel)" },
  { id: "nagai-s1", kind: "scene", book_id: "bells-of-nagasaki", place_ids: ["jp-urakami"], location: "The whole book", location_zh: "全书", text_en: "Nagai, a radiologist at the medical college, already ill with leukaemia, is at work when the bomb falls on 9 August 1945. He describes the relief party he led for days among the dying, finding his wife's remains in the ashes of their kitchen, and his own attempt, as a doctor and a Catholic, to make sense of what had happened to Urakami.", text_zh: "医科大学的放射科医生永井当时已患白血病，1945 年 8 月 9 日原子弹落下时他正在上班。他记下了自己带领救护队在垂死的人中间连续工作的那些天，在自家厨房的灰烬里找到妻子的遗骨，以及他作为医生和天主教徒，试图理解浦上遭遇的这一切。", highlight_en: ["Urakami"], highlight_zh: ["浦上"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Bells_of_Nagasaki" },
  { id: "pale-s1", kind: "scene", book_id: "a-pale-view-of-hills", place_ids: ["jp-inasa"], location: "Chapter 7", location_zh: "第七章", text_en: "Etsuko, living in England after her elder daughter's death, remembers a summer in Nagasaki a few years after the bomb, and one day in particular: the cable car up to the hills of Inasa with her neighbour Sachiko and Sachiko's strange little girl, the harbour below, and how happy they were.", text_zh: "大女儿死后独居英国的悦子，回忆起原子弹爆炸几年之后在长崎度过的一个夏天，特别是其中一天：她同邻居佐知子和佐知子那个古怪的小女儿坐缆车上了稻佐的山，港口在脚下，那天她们多么快活。", highlight_en: ["the hills of Inasa"], highlight_zh: ["稻佐的山"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Pale_View_of_Hills" },
  { id: "ukigumo-s1", kind: "scene", book_id: "floating-clouds", place_ids: ["jp-yakushima"], location: "Final chapters", location_zh: "结尾几章", text_en: "Yukiko and Tomioka became lovers as forestry officials in wartime Indochina; back in ruined Tokyo he will neither keep her nor let her go. When he takes a post on Yakushima she follows him, already ill, and dies alone in the forestry lodging while the rain comes down and he is up in the mountains.", text_zh: "雪子和富冈战时在法属印度支那的林业部门相识相恋；回到一片废墟的东京后，他既不肯同她在一起，又不肯放她走。他到屋久岛任职，已经病重的她跟了去；大雨倾盆，他上山去了，她独自死在林业署的宿舍里。", highlight_en: ["Yakushima"], highlight_zh: ["屋久岛"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Floating_Clouds" }
];
